//  StockCatalog.swift — the film and paper library, read from the bundle.
//
//  `Resources/StockCatalog.json` is generated by `Tools/gen-catalog.py` from
//  the engine's profile directory, so the picker cannot list a stock the
//  engine does not have. Regenerate it when a profile is added.

import Foundation
import Observation

struct Stock: Codable, Identifiable, Hashable, Sendable {
    let id: String
    let name: String
    let stage: String          // "filming" | "printing"
    let use: String            // "still" | "cine"
    let type: String?
    let targetPrint: String?
    let hasPreviewLUT: Bool
    let pairedFilm: String?
    let cover: String?
    let nominalSpeed: Int?
    let speedUnit: String?
    let speedSource: String?
    var channelModel: String? = nil

    var speedLabel: String? {
        guard isFilm, let nominalSpeed else { return nil }
        return "\(speedUnit ?? "ISO") \(nominalSpeed)"
    }

    var isFilm: Bool { stage == "filming" }
    var isPaper: Bool { stage == "printing" }
    var isMonochrome: Bool { channelModel == "monochrome" || channelModel == "chromogenic_monochrome" }
    var isCine: Bool { use == "cine" }
    /// A reversal (slide) film: Provia, Velvia, Ektachrome, Kodachrome.
    ///
    /// The catalogue has carried this since it was generated — `type` is
    /// `"positive"` or `"negative"` and the four slide films are the ones
    /// with no `targetPrint` — and nothing read it. A positive is already a
    /// viewable image, so printing one onto a paper stock is an operation the
    /// engine performs happily and nobody wants.
    var isPositive: Bool { type == "positive" }
    /// Stable catalog identity, independent of localized display names.
    var isExperimental: Bool { isFilm && id.hasSuffix("_experimental") }
    var brand: String { name.split(separator: " ").first.map(String.init) ?? "" }
    /// Generated packaging artwork, separate from legacy catalog cover metadata.
    var packagingArtworkURL: URL? {
        let baseID = id == "kodak_portra_800_push1" || id == "kodak_portra_800_push2" ? "kodak_portra_800" : id
        let version = baseID == "kodak_portra_400" ? "v2" : "v1"
        return StockCatalog.bundle.url(forResource: baseID + "-packaging-" + version,
                                       withExtension: "png", subdirectory: "Resources/FilmCovers")
    }
    var coverURL: URL? {
        cover.flatMap { StockCatalog.bundle.url(forResource: $0, withExtension: nil, subdirectory: "Resources/FilmCovers") }
    }
}

struct StockCatalog: Sendable {
    let stocks: [Stock]

    /// The bundle that carries Resources/: the app, or the test bundle.
    static var bundle: Bundle { Bundle(for: BundleToken.self) }
    private final class BundleToken {}

    static let shared: StockCatalog = {
        let url = bundle.url(forResource: "StockCatalog", withExtension: "json", subdirectory: "Resources")
        if let url, let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode(Wrapper.self, from: data) {
            return StockCatalog(stocks: decoded.stocks)
        }
        return StockCatalog(stocks: [])
    }()

    private struct Wrapper: Decodable { let stocks: [Stock] }

    var films: [Stock] { stocks.filter(\.isFilm) }
    var papers: [Stock] { stocks.filter(\.isPaper) }
    func stock(_ id: String) -> Stock? { stocks.first { $0.id == id } }

    /// Films in the order the picker shows them: still first, brand-grouped,
    /// then cine. Within a brand the order is the catalog's (alphabetical).
    var filmsForPicker: [Stock] {
        let still = films.filter { !$0.isCine }
        let cine = films.filter(\.isCine)
        return still + cine
    }

    /// Films grouped as v3 draws them: **Positive**, then **Negative**.
    ///
    /// Grouped on `type`, which the catalogue has carried since it was
    /// generated — not on the name and not on the artwork's order, which is
    /// handoff §8.6's requirement. Within each group `filmsForPicker`'s order
    /// is kept, so a cine stock still follows the stills of its group rather
    /// than being hoisted.
    ///
    /// The whole catalogue comes back: v3's illustration shows 3 positive and
    /// 4 negative rows, and those are the counts of a *viewport*, not a
    /// filter.
    var filmGroups: [(title: String, films: [Stock])] {
        let ordered = filmsForPicker
        return [("Positive", ordered.filter(\.isPositive)),
                ("Negative", ordered.filter { !$0.isPositive })]
    }

    /// Papers grouped for the picker: Still, then Cine.
    var paperGroups: [(title: String, papers: [Stock])] {
        [("Still", papers.filter { !$0.isCine }), ("Cine", papers.filter(\.isCine))]
    }

    /// Whether `paper` is the declared target of `film` — an honest pairing
    /// versus an approximation (API-SPEC §2's pairing note).
    func isDeclaredPairing(film: String, paper: String) -> Bool {
        stock(film)?.targetPrint == paper
    }
}

// MARK: - Material browser preferences (UI state, outside render parameters)

/// Catalogue IDs, never card positions: favourites survive filtering and sorting.
@MainActor @Observable
final class MaterialBrowserLibrary {
    private let defaults: UserDefaults
    private(set) var favorites: Set<String>
    private(set) var recent: [String]
    private static let favoritesKey = "ui2.materialBrowser.favorites"
    private static let recentKey = "ui2.materialBrowser.recent"
    private static let recentLimit = 20

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        favorites = Set(defaults.stringArray(forKey: Self.favoritesKey) ?? [])
        recent = defaults.stringArray(forKey: Self.recentKey) ?? []
    }

    func toggleFavorite(_ id: String) {
        if !favorites.insert(id).inserted { favorites.remove(id) }
        defaults.set(favorites.sorted(), forKey: Self.favoritesKey)
    }

    func recordUse(_ id: String) {
        recent.removeAll { $0 == id }
        recent.insert(id, at: 0)
        recent = Array(recent.prefix(Self.recentLimit))
        defaults.set(recent, forKey: Self.recentKey)
    }
}

enum MaterialBrowserTab: String { case film, paper }
enum MaterialBrowserFilter: CaseIterable {
    case all, positive, negative, experimental, blackwhiteExperimental, favorites, recent
    static let filmTabs: [Self] = [.all, .positive, .negative, .experimental, .blackwhiteExperimental]
}

@MainActor struct MaterialBrowserChoice: Identifiable {
    static let scanID = "__scan_film__"
    static let diID = "__digital_intermediate__"
    let id: String
    let stock: Stock?

    static func choices(catalog: StockCatalog, tab: MaterialBrowserTab,
                        filter: MaterialBrowserFilter, query: String,
                        favorites: Set<String>, recent: [String]) -> [Self] {
        var choices = tab == .film
            ? catalog.filmGroups.flatMap(\.films).map { Self(id: $0.id, stock: $0) }
            : [Self(id: scanID, stock: nil), Self(id: diID, stock: nil)]
                + catalog.papers.map { Self(id: $0.id, stock: $0) }
        switch filter {
        case .all: break
        case .negative: choices = choices.filter { $0.stock?.isFilm == true && $0.stock?.isPositive == false && $0.stock?.isExperimental == false }
        case .positive: choices = choices.filter { $0.stock?.isPositive == true && $0.stock?.isExperimental == false }
        case .experimental: choices = choices.filter { $0.stock?.isExperimental == true }
        case .blackwhiteExperimental:
            choices = choices.filter { $0.stock?.isExperimental == true && $0.stock?.isMonochrome == true }
        case .favorites: choices = choices.filter { favorites.contains($0.id) }
        case .recent:
            let byID = Dictionary(uniqueKeysWithValues: choices.map { ($0.id, $0) })
            choices = recent.compactMap { byID[$0] }
        }
        let query = query.trimmingCharacters(in: .whitespacesAndNewlines)
        if !query.isEmpty {
            choices = choices.filter {
                ($0.title + " " + $0.subtitle + " " + $0.id).localizedStandardContains(query)
            }
        }
        return choices
    }

    var title: String {
        if let stock {
            if stock.id == "silverphase_neutral_bw_print_experimental" {
                return T("Neutral B&W Print (Experimental)", "中性黑白印相（实验）")
            }
            return stock.name.replacingOccurrences(of: "Professional ", with: "")
                .replacingOccurrences(of: "(Experimental)", with: T("(Experimental)", "（实验）"))
        }
        return id == Self.scanID ? L(.printNone) : L(.printDigitalIntermediate)
    }
    /// Entity packaging and virtual workflow labels share the same renderer.
    var artworkURL: URL? {
        if let stock { return stock.packagingArtworkURL }
        let filename: String
        switch id {
        case Self.scanID: filename = "workflow_film_scan-v1"
        case Self.diID: filename = "workflow_digital_intermediate-v1"
        default: return nil
        }
        return StockCatalog.bundle.url(forResource: filename, withExtension: "png", subdirectory: "Resources/FilmCovers")
    }

    /// Compact display name; the canonical catalog name remains unchanged.
    var cardTitle: String {
        guard let stock else { return title }
        let prefix = stock.brand + " "
        return title.hasPrefix(prefix) ? String(title.dropFirst(prefix.count)) : title
    }

    var subtitle: String {
        guard let stock else {
            return id == Self.scanID ? T("Film scan", "原片扫描") : T("Digital Intermediate", "数字中间片")
        }
        let type = stock.isMonochrome ? (stock.isFilm ? T("B&W negative", "黑白负片") : T("B&W print", "黑白印相")) :
            (stock.isFilm ? L(filmGroup: stock.isPositive ? "Positive" : "Negative") : L(.sectionPaper))
        return type + " · " + (stock.speedLabel ?? (stock.isCine ? T("Motion picture", "电影") : T("Still photography", "静态摄影")))
    }
}
